seq = ""
for line in open("region.fasta"):
    if not line.startswith(">"):
        seq += line.strip()
seq = seq.upper()
n = len(seq)

def rc(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# Find all repeated k-mers (k=15..40) appearing 2+ times
from collections import defaultdict
print("=== Direct repeats (k>=15, 2+ occurrences) ===")
for k in [15,18,20,25,30,40]:
    d = defaultdict(list)
    for i in range(n-k+1):
        d[seq[i:i+k]].append(i+1)
    reps = {kk:vv for kk,vv in d.items() if len(vv)>=2}
    # merge/print notable
    print(f"\nk={k}: {len(reps)} repeated kmers")
    for kk,vv in sorted(reps.items(), key=lambda x:-len(x[1]))[:8]:
        print("  ", kk, vv)

print("\n=== Inverted repeats (palindromes) length >= 12 ===")
for k in [12,15,18,20]:
    seen=set()
    out=[]
    for i in range(n-k+1):
        sub = seq[i:i+k]
        r = rc(sub)
        j = seq.find(r, i+k)  # non-overlapping-ish
        if j!=-1:
            out.append((i+1,j+1,sub))
    print("k=",k, out[:10])
